const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const startDate = '2024-01-02';
  const endDate = '2024-01-03'; // End date is exclusive, so one day after the target date

  // Define a polygon covering Wales and central/southern England
  // This polygon is a simplified representation to cover the specified regions.
  const geometry = ee.Geometry.Polygon([
    [-6.5, 49.8], // Southwest (e.g., Cornwall/Scilly Isles)
    [-6.5, 54.0], // Northwest (e.g., North Wales / Irish Sea)
    [2.0, 54.0],  // Northeast (e.g., Humber Estuary)
    [2.0, 50.5],  // Southeast (e.g., Kent)
    [-6.5, 49.8]  // Closing the polygon
  ]);

  const precipitationThreshold = 35; // millimeters

  // 2. Data Acquisition
  const chirpsDaily = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');
  let filteredCollection = chirpsDaily
    .filterDate(startDate, endDate)
    .filterBounds(geometry);

  // Check if any images were found
  const collectionSize = await filteredCollection.size().getInfo();
  if (collectionSize === 0) {
    console.log(`No CHIRPS daily precipitation data found for ${startDate} in the specified region.`);
    console.log('C1');
    return;
  }

  const image = filteredCollection.first();

  // Get the number of valid pixels for the 'precipitation' band
  const pixelCountDict = await image.select('precipitation').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 5000, // CHIRPS resolution is ~5.5km
    maxPixels: 1e9
  }).getInfo();

  const validPixels = pixelCountDict['precipitation'];

  if (validPixels === 0) {
    console.log(`Image found, but no valid pixels for 'precipitation' within the geometry after selection.`);
    console.log('C2');
    return;
  }

  // 3. Calculation: Find the maximum precipitation in the region
  const maxPrecipitationDict = await image.select('precipitation').reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: geometry,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const maxPrecipitation = maxPrecipitationDict['precipitation'];

  // 4. Validation & Final Answer
  if (maxPrecipitation === null || isNaN(maxPrecipitation)) {
    console.log('Calculation for maximum precipitation failed (result is null or NaN).');
    console.log('C3');
    return;
  }

  console.log(`CHIRPS Image Date: ${startDate}`);
  console.log(`Valid Pixels for 'precipitation': ${validPixels}`);
  console.log(`Max Precipitation on ${startDate}: ${maxPrecipitation.toFixed(2)} mm`);
  console.log(`Threshold: ${precipitationThreshold} mm`);

  if (maxPrecipitation >= precipitationThreshold) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
